    69|export type DeveloperExecutionGuardResult = {
    70|  ok: boolean;
    71|  violations: string[];
    72|  hasAllSections: boolean;
    73|  hasRawCommandOutput: boolean;
    74|};
    75|
    76|/** Raw command output looks like `$ <cmd> ... exit code: N`. */
    77|export function hasRawCommandOutput(answer: string): boolean {
    78|  const text = answer ?? '';
    79|  const hasCommandLine = /^\s*\$\s+\S+/m.test(text);
    80|  const hasExitCode = /\bexit\s+code:\s*\S+/i.test(text) || /→\s*exit\s+\S+/i.test(text);
    81|  return hasCommandLine && hasExitCode;
    82|}
    83|
    84|/** A positive "verified" claim (not the allowed "NOT VERIFIED — ..." line). */
    85|export function claimsVerified(answer: string): boolean {
    86|  const text = (answer ?? '').toLowerCase();
    87|  // Strip the explicit honest negatives so they never count as a claim.
    88|  const stripped = text
    89|    .replace(/not\s+verified[^\n]*/g, '')
    90|    .replace(/typecheck\s+result:/g, '')
    91|    .replace(/test\s+result:/g, '');
    92|  return /\bverified\b|\bverification\s+passed\b|\ball\s+checks\s+pass(?:ed)?\b/.test(stripped);
    93|}
    94|
    95|/** A "deployed/live in production" claim. */
    96|export function claimsDeployed(answer: string): boolean {
    97|  const text = (answer ?? '').toLowerCase();
    98|  const stripped = text
    99|    .replace(/local\s+only/g, '')
   100|    .replace(/not\s+deployed/g, '')
   101|    .replace(/deploy\s+attempted/g, '');
   102|  return /\bstatus:\s*\n?\s*deployed\b/.test(stripped)
   103|    || /\bdeployed\s+to\s+(?:prod|production|live|render)\b/.test(stripped)
   104|    || /\blive\s+in\s+production\b/.test(stripped);
   105|}
   106|
   107|/** A "done/complete/finished" success claim. */
   108|export function claimsDone(answer: string): boolean {
   109|  const text = (answer ?? '').toLowerCase();
   110|  const stripped = text.replace(/no\s+development\s+was\s+completed/g, '');
   111|  return /\b(?:task\s+)?(?:done|completed|complete|finished|shipped)\b/.test(stripped);
   112|}
   113|
   114|/** True when the answer proves a real file diff (changed paths in PROOF). */
   115|export function hasFileDiffProof(answer: string): boolean {
   116|  const text = answer ?? '';
   117|  if (/NO CODE CHANGED/.test(text)) {
   118|    return false;
   119|  }
   120|  // git diff --stat (applied patch) followed by a " path | summary" line, or a
   121|  // git status --short " M path" line.
   122|  return /git\s+diff\s+--stat[^\n]*\n\s*\S+\s*\|/i.test(text)
   123|    || /git\s+status\s+--short:[\s\S]*\n\s*[AM]\s+\S+/i.test(text);
   124|}
   125|
   126|/** True when a live endpoint / commit proof line is present. */
   127|export function hasDeploymentProof(answer: string): boolean {
   128|  const text = answer ?? '';
   129|  return /\bcommit:\s*[0-9a-f]{6,}/i.test(text)
   130|    || /production\s+\/health:\s*healthy/i.test(text)
   131|    || /changed\s+route:\s*live/i.test(text);
   132|}
   133|
   134|/**
   135| * Validate that a candidate answer is a real developer-execution response and not
   136| * narrative-only or an unproven claim.
   137| */
   138|export function validateDeveloperExecutionAnswer(answer: string): DeveloperExecutionGuardResult {
   139|  const text = answer ?? '';
   140|
   141|  // A guard-blocked answer is a recognised compliant terminal state. It carries
   142|  // the sentinel marker, a BLOCKED status, and NO CODE CHANGED — it makes no
   143|  // success claims, so it passes without re-triggering on the violation reasons
   144|  // it quotes. This guarantees enforcement is idempotent.
   145|  if (text.includes(DEVELOPER_EXECUTION_GUARD_MARKER) && /STATUS:\s*\n?\s*BLOCKED/.test(text) && text.includes('NO CODE CHANGED')) {
   146|    return { ok: true, violations: [], hasAllSections: true, hasRawCommandOutput: false };
   147|  }
   148|
   149|  const violations: string[] = [];
   150|
   151|  const missingSections = REQUIRED_DEVELOPER_SECTIONS.filter((header) => !text.includes(header));
   152|  const hasAllSections = missingSections.length === 0;
   153|  if (!hasAllSections) {
   154|    violations.push(`missing required sections: ${missingSections.join(', ')}`);
   155|  }
   156|
   157|  const rawOutput = hasRawCommandOutput(text);
   158|
   159|  // Banned narrative phrases are only tolerated when real proof accompanies them.
   160|  if (!rawOutput) {
   161|    const lower = text.toLowerCase();
   162|    for (const phrase of BANNED_NARRATIVE_PHRASES) {
   163|      if (lower.includes(phrase)) {
   164|        violations.push(`narrative phrase without proof: "${phrase}"`);
   165|      }
   166|    }
   167|  }
   168|
   169|  if (claimsVerified(text) && !rawOutput) {
   170|    violations.push('claims "verified" without raw command output');
   171|  }
   172|
   173|  if (claimsDeployed(text) && !hasDeploymentProof(text)) {
   174|    violations.push('claims "deployed" without live endpoint / commit proof');
   175|  }
   176|
   177|  if (claimsDone(text) && !hasFileDiffProof(text)) {
   178|    violations.push('claims "done/complete" without a real file diff');
   179|  }
   180|
   181|  return {
   182|    ok: violations.length === 0,
   183|    violations,
   184|    hasAllSections,
   185|    hasRawCommandOutput: rawOutput,
   186|  };
   187|}
