   189|/**
   190| * Replacement message returned to the owner when a development answer fails the
   191| * guard. Keeps the strict format so the client renders it consistently and the
   192| * owner immediately sees it was blocked rather than a fake success.
   193| */
   194|export function buildBlockedDeveloperExecutionAnswer(violations: string[]): string {
   195|  const reasons = violations.length > 0 ? violations.map((v) => ` - ${v}`).join('\n') : ' - narrative-only response blocked';
   196|  return [
   197|    `TASK UNDERSTOOD:\nDevelopment-task response blocked by the execution guard (${DEVELOPER_EXECUTION_GUARD_MARKER}).`,
   198|    'FILES INSPECTED:\nnone — output rejected before delivery.',
   199|    'FILES CHANGED:\nNO CODE CHANGED — no development was completed.',
   200|    'COMMANDS RUN:\nNONE — no commands were executed.',
   201|    'TEST RESULT:\nNOT VERIFIED — tests were not run.',
   202|    'TYPECHECK RESULT:\nNOT VERIFIED — typecheck was not run.',
   203|    'STATUS:\nBLOCKED',
   204|    `PROOF:\nBLOCKED — the generated answer ${DEVELOPER_EXECUTION_GUARD_MARKER}:\n${reasons}`,
   205|  ].join('\n\n');
   206|}
   207|
   208|/**
   209| * Enforce developer-execution mode on a candidate answer. Returns the original
   210| * answer when it passes, otherwise a BLOCKED replacement. Never lets a
   211| * narrative-only / unproven answer reach the owner.
   212| */
   213|export function enforceDeveloperExecutionAnswer(answer: string): {
   214|  answer: string;
   215|  enforced: boolean;
   216|  result: DeveloperExecutionGuardResult;
   217|} {
   218|  const result = validateDeveloperExecutionAnswer(answer);
   219|  if (result.ok) {
   220|    return { answer, enforced: false, result };
   221|  }
   222|  return {
   223|    answer: buildBlockedDeveloperExecutionAnswer(result.violations),
   224|    enforced: true,
   225|    result,
   226|  };
