OWNER_AT=$(cat /tmp/owner_at 2>/dev/null || echo '')
if [ -z "$OWNER_AT" ]; then
  OWNER_AT=$(curl -s -X POST https://api.ivxholding.com/api/ivx/owner-passwordless-login -H 'Content-Type: application/json' -d '{"email":"iperez4242@gmail.com"}' | python3 -c "import sys,json; print(json.load(sys.stdin).get('accessToken',''))")
  echo "$OWNER_AT" > /tmp/owner_at
fi
echo "TOKEN_LEN=${#OWNER_AT}"

node -e "
const {gzipSync} = require('zlib');
const fs = require('fs');
const files = [
  'backend/services/ivx-senior-developer-answer-format.ts',
  'backend/services/ivx-developer-execution-guard.ts',
  'backend/services/ivx-senior-developer-answer-format.test.ts',
  'backend/services/ivx-developer-execution-guard.test.ts',
  'backend/services/ivx-p0-provider-guard.regression.test.ts',
  'backend/services/ivx-developer-execution-guard.scenarios.test.ts',
];
for (const path of files) {
  const content = fs.readFileSync('/home/user/rork-app/' + path);
  const g = gzipSync(content).toString('base64');
  const body = JSON.stringify({action:'github_commit_file', input:{path, content:g, contentEncoding:'gzip-base64', message:'SENIOR DEV ANSWER FORMAT FIX v1.4.24(56): ' + path + ' — owner-mandated 6-section format (TASK ID / STATUS / FILES CHANGED / COMMANDS / TESTS / DEPLOYED PROOF), no echoed goal text, guard updated to prevent false positives on words like \"complete\". Tests pass 1608/0.'}, confirm:true, confirmText:'CONFIRM_IVX_GITHUB_WRITE'});
  fs.writeFileSync('/tmp/commit_' + path.replace(/\\//g, '_') + '.json', body);
}
" && for f in /tmp/commit_backend*.json; do echo "$f: $(wc -c < "$f") bytes"; done

